<template>
    <section class="kw-transfer"><p v-if="error" class="workshop-error" role="alert">{{ error }}</p><p v-if="notice" class="workshop-success" role="status">{{ notice }}</p>
        <section class="workshop-panel"><h2>网页剪藏</h2><p class="kw-muted">输入公开 HTTPS 网页，提取文字后预览并新建笔记。登录页、动态渲染页面、内网地址和大网页可能无法读取；不会携带浏览器登录信息。</p><div class="kw-row"><input v-model="url" class="input" type="url" placeholder="https://…" aria-label="剪藏网页地址" /><button id="kw-clip" class="btn" :disabled="busy||!url" @click="clip">读取网页</button></div><template v-if="preview"><label>标题<input v-model="preview.title" class="input" maxlength="100" /></label><label>剪藏正文<textarea v-model="preview.content_md" class="input kw-markdown" /></label><button class="btn btn-primary" :disabled="busy" @click="saveClip">保存为新笔记</button></template></section>
        <section class="workshop-panel"><h2>Markdown 文件夹导入与导出</h2><p class="kw-muted">支持最多500个 .md 文件，总量8MiB，目录最多16层。保留目录层级，同级同名笔记保留原文并跳过；不会上传非 Markdown 文件。导出 ZIP 仅含正文，属性、评论、画布、模板、SOP 和附件请使用知识库的内容/全量备份。</p><div class="kw-row"><label class="btn">选择 Markdown 文件<input id="kw-md-files" type="file" multiple accept=".md" @change="selectFiles" /></label><label class="btn">选择 Markdown 文件夹<input id="kw-md-folder" type="file" webkitdirectory multiple @change="selectFiles" /></label><button class="btn" :disabled="busy" @click="exportFiles">导出 Markdown ZIP</button></div><p v-if="files.length">待导入{{ files.length }}个文件：{{ files.slice(0,5).map(f=>f.path).join('、') }}{{ files.length>5?'…':'' }}</p><button id="kw-import" class="btn btn-primary" :disabled="busy||!files.length" @click="importFiles">确认导入</button><RouterLink class="btn" to="/kb">内容与全量备份</RouterLink></section>
        <button v-if="busy" class="btn" @click="cancel">停止当前操作</button>
    </section>
</template>
<script setup>
import { ref,onBeforeUnmount } from 'vue';
import { kbApi } from '../../api/knowledge-workbench-client.js';
const emit=defineEmits(['changed','open']),url=ref(''),preview=ref(null),files=ref([]),busy=ref(false),error=ref(''),notice=ref('');let controller=new AbortController(),alive=true,generation=0;
async function operation(task){if(busy.value)return;busy.value=true;error.value='';notice.value='';controller=new AbortController();const own=++generation;try{const result=await task(controller.signal);if(alive&&own===generation)return result;}catch(failure){if(alive&&own===generation&&!controller.signal.aborted)error.value=failure.message;}finally{if(alive&&own===generation)busy.value=false;}}
async function clip(){preview.value=null;const result=await operation(signal=>kbApi.clip(url.value,signal));if(result)preview.value=result;}
async function saveClip(){const result=await operation(async signal=>{const note=await kbApi.create({title:preview.value.title},signal);try{await kbApi.saveNote(note.id,{version:note.version,title:preview.value.title,content_md:preview.value.content_md},signal);}catch(failure){throw new Error(failure.message+'；新建的空白笔记已保留，可在笔记列表中继续编辑。');}return note;});if(result){preview.value=null;emit('changed');emit('open',result.id);}}
async function selectFiles(event){const selected=[...event.target.files].filter(f=>/\.md$/i.test(f.name));event.target.value='';files.value=[];if(selected.length>500||selected.reduce((size,f)=>size+f.size,0)>8388608){error.value='最多500个Markdown文件，总量8MiB';return;}const own=++generation;busy.value=true;try{const result=[];for(const file of selected){if(!alive||own!==generation)return;if(file.size>1048576)throw new Error('每个Markdown文件最多1MiB');result.push({path:file.webkitRelativePath||file.name,content:await file.text()});}if(alive&&own===generation)files.value=result;}catch(failure){if(alive)error.value=failure.message;}finally{if(alive&&own===generation)busy.value=false;}}
async function importFiles(){const result=await operation(signal=>kbApi.import(files.value,signal));if(result){notice.value=`已导入${result.imported}篇，保留并跳过${result.skipped}篇已有页面`;files.value=[];emit('changed');}}
async function exportFiles(){const result=await operation(signal=>kbApi.export(signal));if(result){const source=URL.createObjectURL(result),link=document.createElement('a');link.href=source;link.download='knowledge-markdown.zip';link.click();setTimeout(()=>URL.revokeObjectURL(source),1000);notice.value='Markdown压缩包已生成';}}
function cancel(){generation++;controller.abort();busy.value=false;notice.value='已停止；已保存的笔记仍保留。';}
function canLeave(){return !busy.value&&(!(preview.value||files.value.length)||confirm('剪藏预览或待导入文件尚未保存，离开将丢弃。继续？'));}
onBeforeUnmount(()=>{alive=false;controller.abort();generation++;});defineExpose({canLeave,hasUnsaved:()=>busy.value||!!preview.value||files.value.length>0});
</script>
